-- table: sys_i18n（由 cmd/schema-split 生成；改结构直接改本文件）

-- @phase pre
CREATE SEQUENCE public.sys_i18n_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

-- @phase ddl
CREATE TABLE public.sys_i18n (
    id bigint NOT NULL,
    item_key character varying(100) NOT NULL,
    lang character varying(10) NOT NULL,
    item_value text NOT NULL,
    http_code integer DEFAULT 0,
    status smallint DEFAULT 1 NOT NULL,
    create_time timestamp with time zone,
    update_time timestamp with time zone,
    category character varying(20),
    remark character varying(200)
);

ALTER SEQUENCE public.sys_i18n_id_seq OWNED BY public.sys_i18n.id;

ALTER TABLE ONLY public.sys_i18n ALTER COLUMN id SET DEFAULT nextval('public.sys_i18n_id_seq'::regclass);

-- @phase constr
ALTER TABLE ONLY public.sys_i18n
    ADD CONSTRAINT sys_i18n_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.sys_i18n
    ADD CONSTRAINT uk_sys_i18n_key_lang UNIQUE (item_key, lang);

-- @phase idx
CREATE INDEX idx_sys_i18n_category ON public.sys_i18n USING btree (category);

CREATE INDEX idx_sys_i18n_status ON public.sys_i18n USING btree (status);

-- @phase comment
COMMENT ON TABLE public.sys_i18n IS 'i18n 国际化配置表';

COMMENT ON COLUMN public.sys_i18n.item_key IS '文案键';

COMMENT ON COLUMN public.sys_i18n.lang IS '语言代码';

COMMENT ON COLUMN public.sys_i18n.item_value IS '文案值';

COMMENT ON COLUMN public.sys_i18n.http_code IS 'HTTP 状态码';

COMMENT ON COLUMN public.sys_i18n.status IS '状态：0禁用 1启用';

COMMENT ON COLUMN public.sys_i18n.create_time IS '审计 DB-018：由 timestamp 统一为 timestamptz；历史值按会话时区解释';

COMMENT ON COLUMN public.sys_i18n.update_time IS '审计 DB-018：由 timestamp 统一为 timestamptz；历史值按会话时区解释';

COMMENT ON COLUMN public.sys_i18n.category IS '分类：error/ui/msg';

COMMENT ON COLUMN public.sys_i18n.remark IS '备注说明（词条来源文件等）';

