	(1252, 'admin.settings.locales.title', 'zh-CN', '语言', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
	(1253, 'admin.settings.locales.title', 'en-US', 'Languages', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
	(1254, 'admin.settings.ph.gsc_token', 'zh-CN', 'Search Console 给的 content 值（约 43 位）', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
