	(1260, 'admin.settings.ph.site_name', 'zh-CN', '前台站名', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
	(1261, 'admin.settings.ph.site_name', 'en-US', 'Name shown on the public site', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
	(1262, 'admin.settings.roadmap.hint', 'zh-CN', '以下站点级能力目前尚未在后端实现，仅作规划占位，落地后将在此页开放配置：', 200, 1, '2026-11-15 20:36:55.344761+08', '2026-11-15 20:36:55.344761+08', 'admin', 'admin/settings.html'),
