	(1276, 'admin.article.list.lastError', 'zh-CN', '上一次操作未完成：', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1277, 'admin.article.list.lastError', 'en-US', 'The last action did not finish: ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1278, 'admin.article.list.intro', 'zh-CN', '文章是站点的 CMS 内容：它的正文由「内容模板」渲染成访问面上的详情页，也能被列表/卡片类组件当作集合（', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1279, 'admin.article.list.intro', 'en-US', 'Articles are your site''s CMS content: their body is rendered into a public detail page by a content template, and they can also be consumed as a collection (', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1280, 'admin.article.list.introTail', 'zh-CN', '）取用。这里只管内容本身，发布状态在编辑页里看。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1281, 'admin.article.list.introTail', 'en-US', ') by list and card components. This page only manages the content itself; publication state lives on the edit page.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1282, 'admin.article.list.slugStable', 'zh-CN', '路径（slug）是文章的稳定身份', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1283, 'admin.article.list.slugStable', 'en-US', 'The path (slug) is the stable identity of an article', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1284, 'admin.article.list.slugStableTail', 'zh-CN', '：文章集合的链接、访问面的详情页路径都由它派生，建完请不要再改（要改路径请改页面 URL 那种层面的东西，不要靠改 slug —— 那会让已经发出去的链接指向别处）。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1285, 'admin.article.list.slugStableTail', 'en-US', ': collection links and public detail page paths are all derived from it, so do not change it after creation (if a path must change, do it at the page URL level rather than by editing the slug — that would point links you have already published somewhere else).', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1286, 'admin.article.list.createHeading', 'zh-CN', '新建文章', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1287, 'admin.article.list.createHeading', 'en-US', 'New article', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1288, 'admin.article.list.titlePlaceholder', 'zh-CN', '文章标题', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
