	(1293, 'admin.article.list.createSubmit', 'en-US', 'Create and start editing', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
	(1294, 'admin.article.list.createHint', 'zh-CN', '先建一个空壳，正文、摘要、封面与 SEO 字段都在编辑页里填。新建后会自动跳进编辑页。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/articles.html'),
