	(1387, 'admin.article.edit.focusKeywordHint', 'en-US', 'In the checks, ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1388, 'admin.article.edit.focusKeywordHintStrong', 'zh-CN', '关键词密度、关键词位置、H1/H2 是否含关键词', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1389, 'admin.article.edit.focusKeywordHintStrong', 'en-US', 'keyword density, keyword placement, and whether H1/H2 contain the keyword', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1390, 'admin.article.edit.focusKeywordHintTail', 'zh-CN', '都以它为准。留空时这几项一律判「未设置主关键词」——它们是这套评测里权重最高的几项，所以别跳过这一栏。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1391, 'admin.article.edit.focusKeywordHintTail', 'en-US', ' all follow it. When it is left blank these items are all judged "no focus keyword set" — they carry the highest weight in this check, so do not skip this field.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1392, 'admin.article.edit.seoTitleLabel', 'zh-CN', 'SEO 标题', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1393, 'admin.article.edit.seoTitleLabel', 'en-US', 'SEO title', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1394, 'admin.article.edit.seoTitlePlaceholder', 'zh-CN', '留空则按标题评测', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1395, 'admin.article.edit.seoTitlePlaceholder', 'en-US', 'Blank scores against the title', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1396, 'admin.article.edit.seoTitleHint', 'zh-CN', '留空时评测与 SERP 预览用文章标题；搜索引擎结果页看的是这一条。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1397, 'admin.article.edit.seoTitleHint', 'en-US', 'When left blank, the check and the SERP preview use the article title; this is what search result pages show.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
