	(1404, 'admin.article.edit.rescore', 'zh-CN', '重新评分', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1405, 'admin.article.edit.rescore', 'en-US', 'Re-score', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1406, 'admin.article.edit.rescoreHint', 'zh-CN', '「重新评分」只算分，不保存 —— 先看分数再决定要不要改，改完再保存。评分是提示性的，', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1407, 'admin.article.edit.rescoreHint', 'en-US', '"Re-score" only computes the score, it does not save — look at the score before deciding what to change, then save. Scoring is advisory and ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1408, 'admin.article.edit.rescoreHintStrong', 'zh-CN', '不会拦住保存', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1409, 'admin.article.edit.rescoreHintStrong', 'en-US', 'will not block saving', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1410, 'admin.article.edit.rescoreHintTail', 'zh-CN', '：草稿先存下来是常态。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1411, 'admin.article.edit.rescoreHintTail', 'en-US', ': keeping a draft saved is the normal state.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1412, 'admin.article.edit.seoScoreHeading', 'zh-CN', 'SEO 评测', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
