	(1430, 'admin.article.edit.seoScoreLinksTail', 'zh-CN', '（内链数/锚文本/图片 alt）。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1431, 'admin.article.edit.seoScoreLinksTail', 'en-US', ' (internal links / anchor text / image alt).', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1432, 'admin.article.edit.canonicalStrong', 'zh-CN', 'canonical 与结构化数据不由你填', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1433, 'admin.article.edit.canonicalStrong', 'en-US', 'canonical and structured data are not yours to fill in', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1434, 'admin.article.edit.canonicalTail', 'zh-CN', '：发布文章详情页时，系统会按实例的线上路径写 canonical，并按文章类型输出 JSON-LD。评测里的这两项因此恒为达标 —— 它们标出来只是说明「这页产物有这些」，不是待办。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1435, 'admin.article.edit.canonicalTail', 'en-US', ': when an article detail page is published, the system writes canonical from the instance public path and emits JSON-LD per article type. These two items therefore always pass — they are listed only to show that the artifact has them, not as a to-do.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1436, 'admin.article.edit.publishHeading', 'zh-CN', '发布', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1437, 'admin.article.edit.publishHeading', 'en-US', 'Publishing', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1438, 'admin.article.edit.publicPathLabel', 'zh-CN', '线上路径：', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1439, 'admin.article.edit.publicPathLabel', 'en-US', 'Public path: ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1440, 'admin.article.edit.stale', 'zh-CN', '内容有更新，产物待重建', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1441, 'admin.article.edit.stale', 'en-US', 'Content updated, artifact needs a rebuild', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1442, 'admin.article.edit.staleHint', 'zh-CN', '文章改完保存后不会自动变更线上文件 —— 要么等依赖扇出触发的重建，要么在这里手动重新发布一次。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1443, 'admin.article.edit.staleHint', 'en-US', 'Saving the article does not change the live files by itself — either wait for a rebuild triggered by dependency fan-out, or republish manually here.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1444, 'admin.article.edit.upToDate', 'zh-CN', '已是最新', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1445, 'admin.article.edit.upToDate', 'en-US', 'Up to date', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1446, 'admin.article.edit.republish', 'zh-CN', '重新发布', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1447, 'admin.article.edit.republish', 'en-US', 'Republish', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1448, 'admin.article.edit.changePathLabel', 'zh-CN', '修改访问路径', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1449, 'admin.article.edit.changePathLabel', 'en-US', 'Change public path', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1450, 'admin.article.edit.keepRedirect', 'zh-CN', '旧链接保留 301 跳转（不勾则旧链接直接失效）', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1451, 'admin.article.edit.keepRedirect', 'en-US', 'Keep a 301 redirect from the old link (unchecked: the old link stops working immediately)', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1452, 'admin.article.edit.changePathSubmit', 'zh-CN', '改 URL', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1453, 'admin.article.edit.changePathSubmit', 'en-US', 'Change URL', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1454, 'admin.article.edit.changePathHint', 'zh-CN', '改 URL 不动文章内容：正文、SEO 字段、模板绑定都保持原样，只是把产物重建到新路径，并按上面的选择处置旧链接。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1455, 'admin.article.edit.changePathHint', 'en-US', 'Changing the URL leaves the article content alone: body, SEO fields and template bindings all stay as they are; the artifact is simply rebuilt at the new path and the old link is handled as chosen above.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1456, 'admin.article.edit.publishIntro', 'zh-CN', '这篇文章还没有线上详情页。选一套模板与站点工程，发布后即可访问。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1457, 'admin.article.edit.publishIntro', 'en-US', 'This article has no public detail page yet. Pick a template and a site project; it becomes reachable once published.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
