	(1472, 'admin.article.edit.importIntroTail', 'zh-CN', '，新建一个页面草稿并在工作台里打开它。这是一次', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1473, 'admin.article.edit.importIntroTail', 'en-US', ', create a page draft and open it in the workbench. This is a ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1474, 'admin.article.edit.importCopyStrong', 'zh-CN', '复制', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
