	(1496, 'admin.article.edit.importPathLabel', 'zh-CN', '新页面路径', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
