	(1501, 'admin.article.edit.importCreate', 'en-US', 'Create the page and open the canvas', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1502, 'admin.article.edit.importPreviewEmpty', 'zh-CN', '还没有预览。点「预览转换结果」看看正文会变成多少个组件、有没有损失。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1503, 'admin.article.edit.importPreviewEmpty', 'en-US', 'No preview yet. Click "Preview conversion" to see how many components the body becomes and whether anything is lost.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_edit.html'),
	(1504, 'admin.article.translations.heading', 'zh-CN', '文章翻译', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.353792+08', 'admin', 'admin/article_translations.html'),
