	(1915, 'admin.customer_detail.orders.no_projects.link', 'en-US', 'Pages', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/customer_detail.html'),
	(1916, 'admin.customer_detail.orders.no_projects.tail', 'zh-CN', '里建好工程后，这一块会显示该客户在这个工程的消费情况。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/customer_detail.html'),
