	(2313, 'admin.mail.automation_edit.save', 'en-US', 'Save', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2314, 'admin.mail.automation_edit.save_note', 'zh-CN', '保存会推进版本号；已运行的实例继续用它们启动时的版本（改图不影响在跑的人）。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2315, 'admin.mail.automation_edit.save_note', 'en-US', 'Saving advances the version; instances already running keep the version they started with (editing the graph does not affect people mid-flow).', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2316, 'admin.mail.automation_edit.templates_hint', 'zh-CN', '可用模板 key：', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2317, 'admin.mail.automation_edit.templates_hint', 'en-US', 'Available template keys:', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2318, 'admin.mail.automation_edit.trigger.lead', 'zh-CN', '触发方式决定「谁会进入流程」。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2319, 'admin.mail.automation_edit.trigger.lead', 'en-US', 'The trigger decides who enters the flow. ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2320, 'admin.mail.automation_edit.trigger.manual_tail', 'zh-CN', '最可控（后台挑人加入，适合先试跑）；事件触发随业务动作自动发生。注意：批量导入', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2321, 'admin.mail.automation_edit.trigger.manual_tail', 'en-US', ' is the most controllable (you pick the people in the admin, good for a trial run); event triggers happen automatically with business actions. Note: bulk import does ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2322, 'admin.mail.automation_edit.trigger.strong_manual', 'zh-CN', '手工添加', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2323, 'admin.mail.automation_edit.trigger.strong_manual', 'en-US', 'Manual add', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2324, 'admin.mail.automation_edit.trigger.strong_not', 'zh-CN', '不会', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2325, 'admin.mail.automation_edit.trigger.strong_not', 'en-US', 'not', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2326, 'admin.mail.automation_edit.trigger.tail', 'zh-CN', '逐条触发（1000 次查询太贵），需要时用后台批量加入。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
	(2327, 'admin.mail.automation_edit.trigger.tail', 'en-US', ' fire per record (1000 queries would be too expensive); use bulk add in the admin when you need it.', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_automation_edit.html'),
