	(2602, 'admin.mail.marketing.import.consent.strong', 'zh-CN', '已同意', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_marketing.html'),
	(2603, 'admin.mail.marketing.import.consent.strong', 'en-US', 'has consented', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_marketing.html'),
	(2604, 'admin.mail.marketing.import.consent.tail', 'zh-CN', '接收营销邮件（勾选后置为「已订阅」并记录来源）', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_marketing.html'),
	(2605, 'admin.mail.marketing.import.consent.tail', 'en-US', ' to receiving marketing email (ticking it sets them to "subscribed" and records the source)', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_marketing.html'),
