	(2642, 'admin.mail.marketing.related.mail', 'zh-CN', '邮箱设置', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/mail_marketing.html'),
