	(2818, 'admin.orders.heading', 'zh-CN', '订单管理', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2819, 'admin.orders.heading', 'en-US', 'Orders', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2820, 'admin.orders.hint.cancel_refund.lead', 'zh-CN', '取消与退款各是独立用例：取消会归还', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2821, 'admin.orders.hint.cancel_refund.lead', 'en-US', 'Cancelling and refunding are separate use cases: cancelling returns the stock of items ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2822, 'admin.orders.hint.cancel_refund.strong', 'zh-CN', '尚未发货', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2823, 'admin.orders.hint.cancel_refund.strong', 'en-US', 'not yet shipped', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2824, 'admin.orders.hint.cancel_refund.tail', 'zh-CN', '那部分库存，退款只动钱与状态（不归还库存）。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2825, 'admin.orders.hint.cancel_refund.tail', 'en-US', ', while a refund only moves money and status (it does not return stock).', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2826, 'admin.orders.hint.flow.lead', 'zh-CN', '状态流转有', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2827, 'admin.orders.hint.flow.lead', 'en-US', 'Status transitions have ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2828, 'admin.orders.hint.flow.mid', 'zh-CN', '：待付款 → 已付款 → 已发货 → 已完成；待付款 / 已付款可以取消（取消会归还尚未发货那部分库存）；已付款 / 已发货 / 已完成可以退款（', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2829, 'admin.orders.hint.flow.mid', 'en-US', ': pending payment → paid → shipped → completed; pending payment / paid can be cancelled (cancelling returns the stock of items not yet shipped); paid / shipped / completed can be refunded (', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2830, 'admin.orders.hint.flow.mid2', 'zh-CN', ' —— 钱与货分开，退货入库是另一件事）。页面只列出「可能」的目标，', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2831, 'admin.orders.hint.flow.mid2', 'en-US', ' — money and goods are separate, and returning goods to stock is a different flow). The page only lists the "possible" targets, and ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2832, 'admin.orders.hint.flow.strong_edges', 'zh-CN', '合法边', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2833, 'admin.orders.hint.flow.strong_edges', 'en-US', 'legal edges', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2834, 'admin.orders.hint.flow.strong_refund', 'zh-CN', '退款不归还库存', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2835, 'admin.orders.hint.flow.strong_refund', 'en-US', 'a refund does not return stock', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2836, 'admin.orders.hint.flow.strong_server', 'zh-CN', '合法性由服务端裁决', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2837, 'admin.orders.hint.flow.strong_server', 'en-US', 'the server decides what is legal', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2838, 'admin.orders.hint.flow.tail', 'zh-CN', '：选了不允许的边，服务端会把中文原因回显在页面顶部。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2839, 'admin.orders.hint.flow.tail', 'en-US', ': if you pick a disallowed edge, the server echoes the reason at the top of the page.', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2840, 'admin.orders.hint.snapshot.lead', 'zh-CN', '这里的每一单都是', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2841, 'admin.orders.hint.snapshot.lead', 'en-US', 'Each order here is ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2842, 'admin.orders.hint.snapshot.mid', 'zh-CN', '：商品后来改名改价，历史订单里的商品名、规格与单价都不变。金额一律以', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2843, 'admin.orders.hint.snapshot.mid', 'en-US', ': a product may be renamed or repriced later, but the product name, variant and unit price inside a historical order never change. Amounts are always stored in ', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2844, 'admin.orders.hint.snapshot.strong', 'zh-CN', '下单当时的事实快照', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2845, 'admin.orders.hint.snapshot.strong', 'en-US', 'a snapshot taken at checkout time', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2846, 'admin.orders.hint.snapshot.strong_cent', 'zh-CN', '分', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2847, 'admin.orders.hint.snapshot.strong_cent', 'en-US', 'cents', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2848, 'admin.orders.hint.snapshot.tail', 'zh-CN', '存储，页面上换算成元展示（保留两位小数）。', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
	(2849, 'admin.orders.hint.snapshot.tail', 'en-US', ' and shown here converted to the display currency (two decimal places).', 200, 1, '2026-11-15 20:36:55.366509+08', '2026-11-15 20:36:55.366509+08', 'admin', 'admin/orders.html'),
