	(3272, 'admin.product_pricing.lastError', 'zh-CN', '上一次操作未完成：', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3273, 'admin.product_pricing.lastError', 'en-US', 'The last action did not finish: ', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3278, 'prIntro', 'zh-CN', '按规则批量生成售价：成本乘倍数 / 成本加价 / 目标毛利率 / 统一售价，含尾数处理；可对单个 SKU、单个商品的全部变体、或筛选出的商品集应用。算完的售价直接写库（不是运行时计算），应用前先预览，每次应用都留下台账。', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3279, 'prIntro', 'en-US', 'Generate prices in bulk from rules: cost × multiplier, cost + markup, target gross margin or a flat price, with rounding. Apply to a single SKU, to every variant of one product, or to a filtered set of products. The computed prices are written straight to the database (they are not evaluated at runtime); preview before applying, and every run leaves a ledger entry.', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3280, 'prRulesTitle', 'zh-CN', '内置定价规则', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3281, 'prRulesTitle', 'en-US', 'Built-in pricing rules', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
