	(3288, 'prArgs', 'zh-CN', '参数', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3289, 'prArgs', 'en-US', 'Parameters', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3290, 'prRulesNeedCost', 'zh-CN', '（需要成本价）', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3291, 'prRulesNeedCost', 'en-US', ' (requires cost price)', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3292, 'prRulesHint', 'zh-CN', '规则与参数只有服务端一份定义：未知类型、未知参数键、类型不符与取值越界一律拒绝，不接受自由表达式（没有 SQL / 脚本入口）。', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3293, 'prRulesHint', 'en-US', 'Rules and parameters have exactly one definition, on the server: unknown types, unknown parameter keys, mismatched types and out-of-range values are all rejected. Free-form expressions are not accepted (there is no SQL or script entry point).', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3294, 'prRoundHint', 'zh-CN', '尾数处理一律「向上取」：只抬不降，保证按规则算出的售价不会被凑尾数压低。', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
	(3295, 'prRoundHint', 'en-US', 'Rounding always goes up: it only raises a price, so a computed price can never be pushed down to hit a nicer ending.', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:55.421206+08', 'admin', 'admin/product_pricing.html'),
