	(4628, 'admin.blocks.confirm_delete_suffix', 'zh-CN', '」？', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4629, 'admin.blocks.confirm_delete_suffix', 'en-US', '?', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4630, 'admin.blocks.notes_heading', 'zh-CN', '说明', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4631, 'admin.blocks.notes_heading', 'en-US', 'Notes', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4632, 'admin.blocks.notes', 'zh-CN', '全局块 = 跨页面复用的结构片段（对应 WP 的 HTML 块 / template part）。页眉/页脚块在「主题管理 → 设置」里绑定到主题，构建页面时编译期内联进产物——访问面保持纯静态；块内容变更后，绑定了它的主题下页面自动标为待重建。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4633, 'admin.blocks.notes', 'en-US', 'A global block is a structure fragment reused across pages (the WordPress HTML block or template part equivalent). Header and footer blocks are bound to a theme under Theme management → Settings and inlined into the artifacts at build time — the public site stays purely static. When a block changes, the pages of the themes that bind it are marked for rebuild.', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4634, 'admin.blocks.notes_reuse_lead', 'zh-CN', '复用方式（docs/02-D）：', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4635, 'admin.blocks.notes_reuse_lead', 'en-US', 'Reuse modes (docs/02-D): ', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4636, 'admin.blocks.notes_reuse_global', 'zh-CN', '全局引用', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4637, 'admin.blocks.notes_reuse_global', 'en-US', 'Global reference', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4638, 'admin.blocks.notes_reuse_global_tail', 'zh-CN', '＝页面存引用，改一处所有引用页一起更新（页眉/公告栏/信任徽章）；', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4639, 'admin.blocks.notes_reuse_global_tail', 'en-US', ' means the page stores a reference, so editing once updates every referencing page (headers, announcement bars, trust badges); ', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4640, 'admin.blocks.notes_reuse_template', 'zh-CN', '一次性复制', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4641, 'admin.blocks.notes_reuse_template', 'en-US', 'One-off copy', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4642, 'admin.blocks.notes_reuse_template_tail', 'zh-CN', '＝插入时复制完整结构，此后与源块互不影响（商品卡/表单/弹窗）。被引用的全局块删除前须先解除引用。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4689, 'admin.navigations.col.target', 'en-US', 'Opens in', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4643, 'admin.blocks.notes_reuse_template_tail', 'en-US', ' copies the full structure on insert and is independent of the source afterwards (product cards, forms, modals). A referenced global block must be unreferenced before it can be deleted.', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/blocks.html'),
	(4644, 'admin.navigations.no_project', 'zh-CN', '请先在「页面」里创建一个站点工程，再管理前台导航菜单。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4645, 'admin.navigations.no_project', 'en-US', 'Create a site project under Pages before managing front-end navigation.', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4646, 'admin.navigations.heading', 'zh-CN', '导航菜单', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
