INSERT INTO public.sys_i18n VALUES
	(4708, 'admin.navigations.confirm_delete_suffix', 'zh-CN', '」？它的子菜单项会一并删除。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4709, 'admin.navigations.confirm_delete_suffix', 'en-US', '? Its child items are deleted as well.', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4710, 'admin.navigations.action.delete', 'zh-CN', '删除', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4711, 'admin.navigations.action.delete', 'en-US', 'Delete', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigations.html'),
	(4712, 'admin.navigation_translations.heading', 'zh-CN', '导航译文', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4713, 'admin.navigation_translations.heading', 'en-US', 'Navigation translations', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4714, 'admin.navigation_translations.intro', 'zh-CN', '菜单文字不写在页面里，而在导航项上 —— 所以它不出现在页面翻译工作台，改这里的译文才生效。译文按「原文 + 语境」寻址：改菜单文字后旧译文自动失效，构建期回退原文。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4715, 'admin.navigation_translations.intro', 'en-US', 'Menu labels are not stored in the page document but on the navigation items — that is why they never show up in the page translation workbench, and why only edits here take effect. Translations are addressed by source text plus context: after you edit a menu label the old translation expires automatically and the build falls back to the source text.', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4716, 'admin.navigation_translations.dedupe_hint', 'zh-CN', '同一个位置里出现多次的相同文字只列一行（译文按原文寻址，列出多行会让人不知道改哪一行才算数）。', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4717, 'admin.navigation_translations.dedupe_hint', 'en-US', 'The same text appearing several times in one position is listed once (translations are addressed by source text; duplicate rows would leave you unsure which one counts).', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
	(4718, 'admin.navigation_translations.summary_lead', 'zh-CN', '共 ', 200, 1, '2026-11-15 20:36:55.463553+08', '2026-11-15 20:36:55.463553+08', 'admin', 'admin/navigation_translations.html'),
