	(4895, 'admin.analytics.daily.title', 'en-US', 'By day', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4896, 'admin.analytics.intro.after', 'zh-CN', '）：访问面是静态产物直出，服务端不在访客请求路径上，所以计数只能从客户端来。打点失败静默丢弃 —— 统计永远不会影响访客看到的页面。', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4897, 'admin.analytics.intro.after', 'en-US', '): the public site serves static artifacts, so the server is not on the visitor request path and counts can only come from the client. Failed beacons are dropped silently — analytics never affects the page a visitor sees.', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4898, 'admin.analytics.intro.lead', 'zh-CN', '数据由访客浏览器打点（', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4899, 'admin.analytics.intro.lead', 'en-US', 'Counts come from visitor browsers (', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4900, 'admin.analytics.metrics.lead', 'zh-CN', '「浏览数」是页面打开次数（PV）；「独立访客」按匿名标识去重（UV）—— 匿名标识由客户端派生、服务端再加盐哈希后落库，库里既没有 IP 明文，也没有原始 cookie 值。日期按 ', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4901, 'admin.analytics.metrics.lead', 'en-US', '"Page views" counts page opens (PV); "unique visitors" are deduplicated by an anonymous id (UV) — the id is derived on the client and salted and hashed on the server before it is stored, so the database holds neither plain IP addresses nor raw cookie values. Dates are split by the ', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4902, 'admin.analytics.metrics.strong', 'zh-CN', 'UTC 日界', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4903, 'admin.analytics.metrics.strong', 'en-US', 'UTC day boundary', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4904, 'admin.analytics.metrics.tail', 'zh-CN', '切分：产物由全球访客访问，用 UTC 才不会有跨时区的口径歧义。', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4905, 'admin.analytics.metrics.tail', 'en-US', ': artifacts are served to visitors worldwide, and UTC is the only way to avoid ambiguity across time zones.', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4906, 'admin.analytics.no_project.lead', 'zh-CN', '还没有站点工程 —— 统计按工程归集，先去', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4907, 'admin.analytics.no_project.lead', 'en-US', 'No site project yet — analytics is grouped by project, so first create one under ', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4908, 'admin.analytics.no_project.link', 'zh-CN', '页面管理', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4909, 'admin.analytics.no_project.link', 'en-US', 'Pages', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4910, 'admin.analytics.no_project.tail', 'zh-CN', '建一个工程并发布页面。', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html'),
	(4911, 'admin.analytics.no_project.tail', 'en-US', ' and publish a page.', 200, 1, '2026-11-15 20:36:55.492156+08', '2026-11-15 20:36:55.492156+08', 'admin', 'admin/analytics.html') ON CONFLICT DO NOTHING;
