INSERT INTO public.sys_i18n VALUES
	(5826, 'admin.roles.action.permissions', 'zh-CN', '权限分配', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/roles.html'),
	(5827, 'admin.roles.action.permissions', 'en-US', 'Permissions', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/roles.html'),
	(5828, 'admin.roles.perm.title', 'zh-CN', '权限分配：', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5829, 'admin.roles.perm.title', 'en-US', 'Permissions: ', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5830, 'admin.roles.perm.intro', 'zh-CN', '勾选该角色可用的目录、菜单与按钮。勾选子项会自动补齐它所属的菜单与目录（不补齐会出现「接口能调、侧栏却没有入口」的分裂授权）；取消父项会同时取消其下全部子项。保存按整棵树的当前勾选做全量替换。', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5831, 'admin.roles.perm.intro', 'en-US', 'Tick the directories, menus and buttons this role may use. Ticking a child also ticks its parent menu and directory (otherwise the role can call the API but has no sidebar entry); unticking a parent untickes its whole subtree. Saving replaces the entire permission set with the current selection.', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5832, 'admin.roles.perm.back', 'zh-CN', '返回角色列表', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5833, 'admin.roles.perm.back', 'en-US', 'Back to roles', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5834, 'admin.roles.perm.ph.search', 'zh-CN', '搜索菜单名称或权限码', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5835, 'admin.roles.perm.ph.search', 'en-US', 'Search by menu name or permission code', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5836, 'admin.roles.perm.action.all', 'zh-CN', '全选', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5837, 'admin.roles.perm.action.all', 'en-US', 'Select all', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
