	(5841, 'admin.roles.perm.action.expand', 'en-US', 'Expand all', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
	(5842, 'admin.roles.perm.action.collapse', 'zh-CN', '折叠全部', 200, 1, '2026-11-15 20:36:55.543704+08', '2026-11-15 20:36:55.543704+08', 'admin', 'internal/templates/admin/role_permissions.html'),
