	(6825, 'pComboFail', 'en-US', 'Generation failed: ', 200, 1, '2026-11-15 20:36:55.608672+08', '2026-11-15 20:36:55.608672+08', 'product', 'internal/templates/admin/product_detail.html'),
	(1370, 'admin.article.edit.bodyHint', 'zh-CN', '正文支持标题（h1~h5 原样保留，不降级）、段落、列表、引用、代码块、表格、折叠块、水平线、链接与图片；白名单之外的元素（script / style / iframe 等）与一切 on* 事件属性会在保存时被清洗掉。正文里写的标题会进入 SEO 的标题结构评测。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
	(1371, 'admin.article.edit.bodyHint', 'en-US', 'The body supports headings (h1–h5 kept as-is, never downgraded), paragraphs, lists, quotes, code blocks, tables, collapsible blocks, horizontal rules, links and images. Elements outside the allowlist (script / style / iframe …) and every on* event attribute are stripped on save. Headings written in the body feed the SEO heading-structure check.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
	(1486, 'admin.article.edit.importWhitelistMid', 'zh-CN', '正文保存时会过一遍富文本白名单（段落、标题 h1~h5、列表、引用、代码块、表格、折叠块、水平线、链接、图片），', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
	(1487, 'admin.article.edit.importWhitelistMid', 'en-US', 'A rich-text allowlist (paragraphs, headings h1–h5, lists, quotes, code blocks, tables, collapsible blocks, horizontal rules, links, images) runs over the body when it is saved, ', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
	(1488, 'admin.article.edit.importWhitelistStrong', 'zh-CN', '白名单之外的元素', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html') ON CONFLICT DO NOTHING;
INSERT INTO public.sys_i18n VALUES
	(1489, 'admin.article.edit.importWhitelistStrong', 'en-US', 'elements outside the allowlist', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
	(1490, 'admin.article.edit.importWhitelistTail', 'zh-CN', ' —— 它们在保存那一刻就被剥掉了，导入自然也看不到。需要别的块级元素，请到画布里添加对应组件。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.610944+08', 'admin', 'admin/article_edit.html'),
