INSERT INTO public.sys_i18n VALUES
	(6929, 'admin.pages.receipts.last_converge', 'en-US', 'Last convergence', 200, 1, '2026-11-15 20:36:55.627026+08', '2026-11-15 20:36:55.627026+08', 'admin', 'admin/pages.html'),
	(6930, 'admin.pages.receipts.action', 'zh-CN', '收敛例程每分钟兜底一次；持续积压请查服务日志（scene=publication）与线上路径一致性，必要时人工核对后再处理。', 200, 1, '2026-11-15 20:36:55.627026+08', '2026-11-15 20:36:55.627026+08', 'admin', 'admin/pages.html'),
	(6931, 'admin.pages.receipts.action', 'en-US', 'The converger sweeps once a minute; if the backlog persists, check the service log (scene=publication) and the consistency of live paths before acting.', 200, 1, '2026-11-15 20:36:55.627026+08', '2026-11-15 20:36:55.627026+08', 'admin', 'admin/pages.html'),
	(6932, 'admin.pages.receipts.ok', 'zh-CN', '发布回执收敛正常：没有待收敛的回执。', 200, 1, '2026-11-15 20:36:55.627026+08', '2026-11-15 20:36:55.627026+08', 'admin', 'admin/pages.html'),
	(6933, 'admin.pages.receipts.ok', 'en-US', 'Publication receipts converged: nothing is pending.', 200, 1, '2026-11-15 20:36:55.627026+08', '2026-11-15 20:36:55.627026+08', 'admin', 'admin/pages.html'),
	(6934, 'admin.plugins.patrol.orphans_title', 'zh-CN', '产物对账巡检：孤儿 schema', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6935, 'admin.plugins.patrol.orphans_title', 'en-US', 'Artifact reconciliation: orphan schemas', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6936, 'admin.plugins.patrol.orphans_desc', 'zh-CN', '这些 schema 在数据库里还在，但注册表里已经没有对应插件（卸载未清干净，或 schema 是手工建的）。巡检不自动清理：DROP SCHEMA ... CASCADE 会连里面的数据一起删除，请先确认表里有没有需要保留的数据。', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6937, 'admin.plugins.patrol.orphans_desc', 'en-US', 'These schemas still exist in the database, but no matching plugin remains in the registry (an incomplete uninstall, or a schema created by hand). The patrol never cleans up automatically: DROP SCHEMA ... CASCADE deletes the data inside as well, so first confirm whether the tables hold anything worth keeping.', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6938, 'admin.plugins.patrol.col_tables', 'zh-CN', '表数量', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6939, 'admin.plugins.patrol.col_tables', 'en-US', 'Tables', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6940, 'admin.plugins.patrol.col_hint', 'zh-CN', '处理建议', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6941, 'admin.plugins.patrol.col_hint', 'en-US', 'Recommended action', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6942, 'admin.plugins.patrol.hint_empty', 'zh-CN', '空 schema，确认后可交由 DBA 手工 DROP', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6943, 'admin.plugins.patrol.hint_empty', 'en-US', 'Empty schema; once confirmed, a DBA can drop it manually', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6944, 'admin.plugins.patrol.hint_filled', 'zh-CN', '里面有表，先确认数据是否还需要，再决定是否 DROP', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6945, 'admin.plugins.patrol.hint_filled', 'en-US', 'Contains tables; confirm whether the data is still needed before dropping', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6946, 'admin.plugins.patrol.missing_title', 'zh-CN', '产物对账巡检：注册行缺少 schema', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6947, 'admin.plugins.patrol.missing_title', 'en-US', 'Artifact reconciliation: registry rows missing their schema', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6948, 'admin.plugins.patrol.missing_desc', 'zh-CN', '这些插件声明了数据结构版本，但数据库里的 schema 不存在 —— 构建装配会在建表时失败。重装该插件即可重建（安装会先清旧 schema 再跑迁移）。', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6949, 'admin.plugins.patrol.missing_desc', 'en-US', 'These plugins declare a schema version, but the schema does not exist in the database — assembly will fail while creating tables. Reinstalling the plugin rebuilds it (install drops the old schema first, then runs migrations).', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6950, 'admin.plugins.patrol.orphan_storage_title', 'zh-CN', '产物对账巡检：孤儿存储目录', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6951, 'admin.plugins.patrol.orphan_storage_title', 'en-US', 'Artifact reconciliation: orphan storage directories', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6952, 'admin.plugins.patrol.orphan_storage_desc', 'zh-CN', '这些目录还留在磁盘上，但注册表里已经没有对应插件（卸载时删除目录失败）。巡检不自动删：目录里可能有还没迁走的资产，请先确认内容再手工删除。', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6953, 'admin.plugins.patrol.orphan_storage_desc', 'en-US', 'These directories are still on disk, but no matching plugin remains in the registry (directory removal failed during uninstall). The patrol never deletes automatically: the directory may hold assets that were not migrated away, so check the contents before removing it by hand.', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(7330, 'admin.permissions.empty.title', 'en-US', 'No permissions yet', 200, 1, '2026-11-15 20:36:55.683358+08', '2026-11-15 20:36:55.683358+08', 'admin', 'admin/permissions.html: 空态标题'),
	(6954, 'admin.plugins.patrol.missing_storage_title', 'zh-CN', '产物对账巡检：注册行缺少存储目录', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6955, 'admin.plugins.patrol.missing_storage_title', 'en-US', 'Artifact reconciliation: registry rows missing their storage directory', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6956, 'admin.plugins.patrol.missing_storage_desc', 'zh-CN', '这些插件在注册表里，但磁盘上的目录不见了 —— 构建装配会静默跳过它们（组件库里少一组组件而没有任何提示）。重装该插件即可恢复。', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6957, 'admin.plugins.patrol.missing_storage_desc', 'en-US', 'These plugins are in the registry, but their directories are gone from disk — assembly silently skips them (a whole component group disappears from the palette with no warning). Reinstalling the plugin restores it.', 200, 1, '2026-11-15 20:36:55.628811+08', '2026-11-15 20:36:55.628811+08', 'admin', 'admin/plugins.html'),
	(6958, 'admin.inventory.actionDone', 'zh-CN', '操作已完成', 200, 1, '2026-11-15 20:36:55.631437+08', '2026-11-15 20:36:55.631437+08', 'inventory', 'internal/module/product/inventory/inbound/http/inventory_page_handle.go'),
	(6959, 'admin.inventory.actionDone', 'en-US', 'Done.', 200, 1, '2026-11-15 20:36:55.631437+08', '2026-11-15 20:36:55.631437+08', 'inventory', 'internal/module/product/inventory/inbound/http/inventory_page_handle.go'),
