	(7196, 'admin.theme_settings.structure_templates', 'zh-CN', '结构模板（页眉 / 页脚）', 200, 1, '2026-11-15 20:36:55.654853+08', '2026-11-15 20:36:55.654853+08', 'admin', ''),
