	(7345, 'admin.inventory_sources.list.emptyTitle', 'zh-CN', '还没有货源', 200, 1, '2026-11-15 20:36:55.686992+08', '2026-11-15 20:36:55.686992+08', 'admin', 'admin/inventory_sources.html: 空态标题（无筛选条件时）'),
	(7346, 'admin.inventory_sources.list.emptyTitle', 'en-US', 'No sources yet', 200, 1, '2026-11-15 20:36:55.686992+08', '2026-11-15 20:36:55.686992+08', 'admin', 'admin/inventory_sources.html: 空态标题（无筛选条件时）'),
