INSERT INTO public.sys_i18n VALUES
	(7500, 'admin.customers.action.enable', 'en-US', 'Enable', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/customers.html + admin/customer_detail.html: 状态按钮动词'),
	(7501, 'admin.returns.note.requested', 'zh-CN', '客户已提交，等待审核：同意后可以勾「立即完成入库 + 退款」（货已经在手上时），也可以等货到仓库再点确认收货。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7502, 'admin.returns.note.requested', 'en-US', 'The customer has submitted this request and it is waiting for review. If you already have the goods, tick "Approve and complete restock + refund now"; otherwise wait for the goods to reach the warehouse and then confirm receipt.', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7503, 'admin.returns.note.approved', 'zh-CN', '已同意，等待收货：货到仓库后点下面的「确认收货并退货」—— 它会先入库、入库成功后立刻退款。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7504, 'admin.returns.note.approved', 'en-US', 'Approved and waiting for the goods. Once they reach the warehouse, click "Confirm receipt and restock" below — it restocks first and refunds right after the restock succeeds.', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7505, 'admin.returns.note.received', 'zh-CN', '货已入库，但退款没做完：点下面的「补退款」重试退款即可（入库那一步已完成，不会重复加库存）。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7506, 'admin.returns.note.received', 'en-US', 'The goods are restocked but the refund did not finish. Click "Retry refund" below (the restock step is already done — stock is never added twice).', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7507, 'admin.returns.note.completed', 'zh-CN', '这单已完成：货已入库、款已退。没有可执行的操作。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7508, 'admin.returns.note.completed', 'en-US', 'This request is complete: the goods were restocked and the refund was paid out. There is nothing left to do.', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7509, 'admin.returns.note.rejected', 'zh-CN', '这单已被拒绝（终态）。客户如有异议，需要他重新提交退货申请。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7510, 'admin.returns.note.rejected', 'en-US', 'This request was rejected (a terminal state). If the customer disagrees, they have to submit a new return request.', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7511, 'admin.returns.note.cancelled', 'zh-CN', '客户已撤销这单申请（终态）。没有可执行的操作。', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(7512, 'admin.returns.note.cancelled', 'en-US', 'The customer cancelled this request (a terminal state). There is nothing left to do.', 200, 1, '2026-11-15 20:36:55.718201+08', '2026-11-15 20:36:55.718201+08', 'admin', 'admin/returns.html: 当前状态说明（.help）'),
	(1326, 'admin.article.list.footHint', 'zh-CN', '按更新时间倒序排列，每页 20 篇，用分页条看更早的文章。「未发布」表示这篇文章还没有线上详情页 —— 不一定是问题（草稿就该是未发布），编辑页的「发布」区块里能看到它当前缺什么。', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.721399+08', 'admin', 'admin/articles.html'),
	(1327, 'admin.article.list.footHint', 'en-US', 'Sorted by update time, newest first; 20 per page — use the pager to reach older posts. "Unpublished" means the article has no public detail page yet — that is not necessarily a problem (a draft should be unpublished), and the publishing section of the edit page shows what it is still missing.', 200, 1, '2026-11-15 20:36:55.353792+08', '2026-11-15 20:36:55.721399+08', 'admin', 'admin/articles.html'),
	(7513, 'admin.blocks.impact.badgeTail', 'zh-CN', ' 个页面有更新未发布', 200, 1, '2026-11-15 20:36:55.722848+08', '2026-11-15 20:36:55.722848+08', 'admin', 'admin/blocks.html: 页头待重建徽章的计数后缀'),
	(7514, 'admin.blocks.impact.badgeTail', 'en-US', ' pages have unpublished changes', 200, 1, '2026-11-15 20:36:55.722848+08', '2026-11-15 20:36:55.722848+08', 'admin', 'admin/blocks.html: 页头待重建徽章的计数后缀'),
	(7517, 'admin.blocks.list_empty', 'zh-CN', '还没有全局块。页眉 / 页脚块在「主题管理 → 设置」里绑定到主题，构建页面时编译期内联；区块用于跨页面复用的结构片段，工作台「全局块」页签可一键引用。', 200, 1, '2026-11-15 20:36:55.722848+08', '2026-11-15 20:36:55.722848+08', 'admin', 'admin/blocks.html: 合并成一张表后的唯一空态'),
	(7518, 'admin.blocks.list_empty', 'en-US', 'No global blocks yet. Bind header / footer blocks to a theme under Theme management → Settings so they are inlined into pages at build time; blocks are structure fragments reused across pages and can be inserted from the Global blocks tab in the workbench.', 200, 1, '2026-11-15 20:36:55.722848+08', '2026-11-15 20:36:55.722848+08', 'admin', 'admin/blocks.html: 合并成一张表后的唯一空态'),
	(7519, 'admin.plugins.patrol.title', 'zh-CN', '产物对账巡检', 200, 1, '2026-11-15 20:36:55.724873+08', '2026-11-15 20:36:55.724873+08', 'admin', 'internal/templates/admin/plugins.html: 巡检折叠卡 summary 标题'),
	(7520, 'admin.plugins.patrol.title', 'en-US', 'Artifact reconciliation', 200, 1, '2026-11-15 20:36:55.724873+08', '2026-11-15 20:36:55.724873+08', 'admin', 'internal/templates/admin/plugins.html: 巡检折叠卡 summary 标题'),
	(7521, 'admin.plugins.patrol.badge_kinds', 'zh-CN', '类不一致', 200, 1, '2026-11-15 20:36:55.724873+08', '2026-11-15 20:36:55.724873+08', 'admin', 'internal/templates/admin/plugins.html: 不一致类数量词（模板在其前面输出数字与空格）'),
