	(7897, 'admin.coupons.status.unknown_lead', 'en-US', '(unknown status: ', 200, 1, '2026-11-15 20:36:55.748791+08', '2026-11-15 20:36:55.748791+08', 'admin', 'admin/order/coupons.html: 未知状态文案 ①（拼接段，英文以空格结尾）'),
	(7898, 'admin.coupons.status.unknown_tail', 'zh-CN', '）', 200, 1, '2026-11-15 20:36:55.748791+08', '2026-11-15 20:36:55.748791+08', 'admin', 'admin/order/coupons.html: 未知状态文案 ②'),
