	(8091, 'admin.order_new.ph.coupon', 'en-US', 'optional; the server-side calculation wins', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 优惠码输入框占位符'),
	(8092, 'admin.order_new.amount.hint.lead', 'zh-CN', '小计与合计由服务端按商品价格算出，页面不提供输入；填了优惠码就以', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ①（拼接段，英文以空格结尾）'),
	(8093, 'admin.order_new.amount.hint.lead', 'en-US', 'Subtotal and total are computed by the server from product prices and cannot be typed here; when a coupon code is given the discount comes from ', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ①（拼接段，英文以空格结尾）'),
	(8094, 'admin.order_new.amount.hint.strong_coupon', 'zh-CN', '服务端试算', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ②（粗体段）'),
	(8095, 'admin.order_new.amount.hint.strong_coupon', 'en-US', 'the server-side calculation', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ②（粗体段）'),
	(8096, 'admin.order_new.amount.hint.mid', 'zh-CN', '的折扣为准，核销与建单同事务。', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ③（拼接段，英文以空格结尾）'),
	(8097, 'admin.order_new.amount.hint.mid', 'en-US', ', and redemption happens in the same transaction as order creation. ', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ③（拼接段，英文以空格结尾）'),
	(8098, 'admin.order_new.amount.hint.strong_discount', 'zh-CN', '没有人工折扣入口', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ④（粗体段）'),
	(8099, 'admin.order_new.amount.hint.strong_discount', 'en-US', 'There is no manual discount input', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ④（粗体段）'),
	(8100, 'admin.order_new.amount.hint.tail', 'zh-CN', '：能填折扣的收银台等于把成交价交给填表人。', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ⑤（尾段）'),
	(8101, 'admin.order_new.amount.hint.tail', 'en-US', ': a checkout that accepts a typed discount hands the final price to whoever fills the form.', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 金额说明 ⑤（尾段）'),
