INSERT INTO public.sys_i18n VALUES
	(8113, 'admin.order_new.field.remark', 'en-US', 'Customer note', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 客户备注字段标签'),
	(8114, 'admin.order_new.ph.remark', 'zh-CN', '客户说的话（可选）', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 客户备注输入框占位符'),
	(8115, 'admin.order_new.ph.remark', 'en-US', 'what the customer said (optional)', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 客户备注输入框占位符'),
	(8116, 'admin.order_new.field.admin_note', 'zh-CN', '后台备注', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 后台备注字段标签'),
	(8117, 'admin.order_new.field.admin_note', 'en-US', 'Staff note', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 后台备注字段标签'),
	(8118, 'admin.order_new.ph.admin_note', 'zh-CN', '这单的来龙去脉（如「电话单，客户要求顺丰」）', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 后台备注输入框占位符'),
	(8119, 'admin.order_new.ph.admin_note', 'en-US', 'context for this order (e.g. "phone order, customer asked for SF Express")', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 后台备注输入框占位符'),
	(8120, 'admin.order_new.section.account', 'zh-CN', '客户账号', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 表单区标题「客户账号」'),
	(8121, 'admin.order_new.section.account', 'en-US', 'Customer account', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 表单区标题「客户账号」'),
	(8122, 'admin.order_new.field.provision', 'zh-CN', '同时给客户开号，并把初始密码发到这个邮箱', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 「同时开号」复选框标签'),
	(8123, 'admin.order_new.field.provision', 'en-US', 'Also create a customer account and mail the initial password to this address', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 「同时开号」复选框标签'),
	(8124, 'admin.order_new.provision.off_hint', 'zh-CN', '默认不开号：订单照常落库，客户不会收到任何邮件，也无法在账户中心看到这单（需要人工告知进度）。勾选后系统才会给该邮箱建号并发初始密码；邮箱已有账号时只把这单关联过去，绝不会改密码、也不会重复发信。', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 未勾选开号时的说明'),
	(8125, 'admin.order_new.provision.off_hint', 'en-US', 'No account is created by default: the order is saved as usual, the customer receives no mail and cannot see this order in the account center (progress must be reported manually). Tick the box above and the system creates an account for this email and mails the initial password; if the email already has an account we only link this order to it — the password is never changed and no mail is re-sent.', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/order_new.html: 未勾选开号时的说明'),
	(8126, 'admin.orders.action.create', 'zh-CN', '代客建单', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/orders.html: 列表页工具条「代客建单」入口'),
	(8127, 'admin.orders.action.create', 'en-US', 'Create order on behalf', 200, 1, '2026-11-15 20:36:55.753196+08', '2026-11-15 20:36:55.753196+08', 'admin', 'admin/order/orders.html: 列表页工具条「代客建单」入口'),
