INSERT INTO public.sys_i18n VALUES
	(10363, 'ErrShippingBaseFeeInvalid', 'zh-CN', '基础运费必须是不小于 0 的数字（单位：元，最多两位小数），且不超过 10000 元', 400, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'project', 'project/inbound/http: 站点设置页保存基础运费时校验（与读取侧同一判据）'),
	(10364, 'ErrShippingBaseFeeInvalid', 'en-US', 'The base shipping fee must be a number of at least 0 (in yuan, up to 2 decimals) and no more than 10000', 400, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'project', 'project/inbound/http: 站点设置页保存基础运费时校验（与读取侧同一判据）'),
	(10365, 'ErrShippingFreeThresholdInvalid', 'zh-CN', '满额免运费门槛必须是不小于 0 的数字（单位：元，最多两位小数），且不超过 10000 元；留空或 0 表示不启用', 400, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'project', 'project/inbound/http: 站点设置页保存免运费门槛时校验（与读取侧同一判据）'),
	(10366, 'ErrShippingFreeThresholdInvalid', 'en-US', 'The free-shipping threshold must be a number of at least 0 (in yuan, up to 2 decimals) and no more than 10000; leave it empty or 0 to disable', 400, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'project', 'project/inbound/http: 站点设置页保存免运费门槛时校验（与读取侧同一判据）'),
	(10367, 'admin.settings.section.shipping', 'zh-CN', '运费', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10368, 'admin.settings.section.shipping', 'en-US', 'Shipping', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10369, 'admin.settings.field.shipping_base_fee', 'zh-CN', '基础运费（元）', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10370, 'admin.settings.field.shipping_base_fee', 'en-US', 'Base shipping fee (yuan)', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10371, 'admin.settings.ph.shipping_base_fee', 'zh-CN', '留空或 0 = 不收运费', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10372, 'admin.settings.ph.shipping_base_fee', 'en-US', 'Leave empty or 0 to charge nothing', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10373, 'admin.settings.hint.shipping', 'zh-CN', '结算时对每单收取的固定运费，单位元（最多两位小数，上限 1 万元）。留空或填 0 = 不收运费。它只影响运费：商品小计仍由订单域现算，不会因为这个值变动。小计达到下面的门槛、或下单客户有免运费会员权益时，这一笔会被免掉。', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10374, 'admin.settings.hint.shipping', 'en-US', 'A fixed fee charged per order at checkout, in yuan (up to 2 decimals, max 10000). Leave it empty or 0 to charge nothing. It only affects shipping: the item subtotal is still computed by the order module and never changes because of this value. The fee is waived once the subtotal reaches the threshold below, or when the customer holds a free-shipping membership benefit.', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10375, 'admin.settings.field.shipping_free_threshold', 'zh-CN', '满额免运费门槛（元）', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10376, 'admin.settings.field.shipping_free_threshold', 'en-US', 'Free shipping threshold (yuan)', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10377, 'admin.settings.ph.shipping_free_threshold', 'zh-CN', '留空或 0 = 不启用', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10378, 'admin.settings.ph.shipping_free_threshold', 'en-US', 'Leave empty or 0 to disable', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10379, 'admin.settings.hint.shipping_threshold', 'zh-CN', '商品小计达到这个金额就免掉上面的基础运费（单位元）。留空或填 0 = 不启用满额免运费。它与基础运费各自独立：填 50 表示买满 50 元免运费，与那笔运费是多少无关。', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10380, 'admin.settings.hint.shipping_threshold', 'en-US', 'Once the item subtotal reaches this amount the base shipping fee above is waived (in yuan). Leave it empty or 0 to disable free shipping by threshold. It is independent of the base fee: 50 means free shipping on orders of 50 yuan or more, regardless of how large that fee is.', 200, 1, '2026-11-15 20:36:55.892533+08', '2026-11-15 20:36:55.892533+08', 'admin', 'internal/templates/admin/project/settings.html'),
	(10381, 'site.fragment.comment.title', 'zh-CN', '评论', 200, 1, '2026-11-15 20:36:55.897821+08', '2026-11-15 20:36:55.897821+08', 'ui', 'runtimefragment comment fragments'),
