	(10528, 'admin.menus.field.permissions', 'en-US', 'Permissions', 200, 1, '2026-11-15 20:36:55.908798+08', '2026-11-15 20:36:55.908798+08', 'admin', 'internal/templates/admin/system/menu_perm_field.html: 表单字段'),
	(10529, 'admin.menus.field.permissions_hint', 'zh-CN', '菜单与按钮至少绑一个权限点，可以绑多个；目录 / iframe / 外链不允许绑。', 200, 1, '2026-11-15 20:36:55.908798+08', '2026-11-15 20:36:55.908798+08', 'admin', 'internal/templates/admin/system/menu_perm_field.html: 规则说明'),
	(10530, 'admin.menus.field.permissions_hint', 'en-US', 'Menus and buttons need at least one permission and may bind several; directories, iframes and external links must not bind any.', 200, 1, '2026-11-15 20:36:55.908798+08', '2026-11-15 20:36:55.908798+08', 'admin', 'internal/templates/admin/system/menu_perm_field.html: 规则说明'),
