	(10684, 'admin.system.group_missing', 'en-US', 'A config group is missing. Run the database migrations (make migrate) and reopen this page.', 200, 1, '2026-11-15 20:36:55.977584+08', '2026-11-15 20:36:55.977584+08', 'admin', 'missing group hint'),
	(10685, 'admin.system.err.lang_unknown', 'zh-CN', '选择的默认语言不在字典里（可能已被停用），请重新选择', 200, 1, '2026-11-15 20:36:55.977584+08', '2026-11-15 20:36:55.977584+08', 'admin', '语言不在字典'),
	(10686, 'admin.system.err.lang_unknown', 'en-US', 'The selected default language is not in the dictionary (it may be disabled). Pick another one.', 200, 1, '2026-11-15 20:36:55.977584+08', '2026-11-15 20:36:55.977584+08', 'admin', 'language not in dictionary'),
