	(10698, 'admin.page.langs.title', 'en-US', 'Language output scope', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：面板标题（该页语言产出范围） (en)'),
	(10699, 'admin.page.langs.col.lang', 'zh-CN', '语言', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「语言」'),
	(10700, 'admin.page.langs.col.lang', 'en-US', 'Language', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「语言」 (en)'),
	(10701, 'admin.page.langs.col.status', 'zh-CN', '状态', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「状态」'),
	(10702, 'admin.page.langs.col.status', 'en-US', 'Status', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「状态」 (en)'),
	(10703, 'admin.page.langs.col.note', 'zh-CN', '说明', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「说明」'),
