	(10705, 'admin.page.langs.col.actions', 'zh-CN', '操作', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「操作」'),
	(10706, 'admin.page.langs.col.actions', 'en-US', 'Actions', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：表头「操作」 (en)'),
	(10707, 'admin.page.langs.empty', 'zh-CN', '这个页面还没有可展示的语言（站点语言清单为空）。', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：空态整行'),
	(10708, 'admin.page.langs.empty', 'en-US', 'This page has no languages to show yet (the site language list is empty).', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：空态整行 (en)'),
	(10709, 'admin.page.langs.action.exclude', 'zh-CN', '排除', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：行内动作「排除」'),
	(10710, 'admin.page.langs.action.exclude', 'en-US', 'Exclude', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：行内动作「排除」 (en)'),
	(10711, 'admin.page.langs.action.restore', 'zh-CN', '恢复', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：行内动作「恢复」'),
	(10712, 'admin.page.langs.action.restore', 'en-US', 'Restore', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：行内动作「恢复」 (en)'),
	(10713, 'admin.page.langs.action.keep', 'zh-CN', '始终产出', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：默认语言不可排除的提示'),
	(10714, 'admin.page.langs.action.keep', 'en-US', 'Always published', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：默认语言不可排除的提示 (en)'),
	(10715, 'admin.page.langs.note', 'zh-CN', '排除某语言会同时下线该语言已发布的产物（访问面入口随之消失），它也不再出现在语言切换器、hreflang 与 sitemap 里；恢复只解除排除，重新上线请走常规发布。', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：面板底部说明'),
	(10716, 'admin.page.langs.note', 'en-US', 'Excluding a language also takes its published artifacts offline (the public entry disappears with it), and it drops out of the language switcher, hreflang and sitemap; restoring only lifts the exclusion, so use the normal publish entry to put it back online.', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：面板底部说明 (en)'),
	(10717, 'admin.page.langs.excluded', 'zh-CN', '已排除该语言并下线其产物', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：排除成功回执'),
	(10718, 'admin.page.langs.excluded', 'en-US', 'Language excluded and its artifacts taken offline', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：排除成功回执 (en)'),
	(10719, 'admin.page.langs.restored', 'zh-CN', '已解除排除：该语言重新参与本页的产出（重新发布走常规发布入口）', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：恢复成功回执'),
	(10720, 'admin.page.langs.restored', 'en-US', 'Exclusion lifted: the language participates in the output of this page again (use the normal publish entry to put it back online)', 200, 1, '2026-11-15 20:36:55.986685+08', '2026-11-15 20:36:55.986685+08', 'admin', 'V4 语言面板：恢复成功回执 (en)'),
