INSERT INTO public.sys_i18n VALUES
	(11449, 'admin.ai.mcp.token.once.hint', 'en-US', 'Copy it somewhere safe now. Only a hash is stored, so once this panel is gone the token cannot be recovered — you would create a new one.', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 一次性明文提示正文'),
	(11450, 'admin.ai.mcp.token.once.hint', 'zh-CN', '现在复制并保存到安全的地方。库里只存哈希，关掉这块之后再也看不到明文，只能重新生成。', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 一次性明文提示正文'),
	(11451, 'admin.ai.mcp.token.once.title', 'en-US', 'This token is shown once', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 一次性明文提示标题'),
	(11452, 'admin.ai.mcp.token.once.title', 'zh-CN', '令牌只显示这一次', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 一次性明文提示标题'),
	(11453, 'admin.ai.mcp.token.revoke', 'en-US', 'Revoke', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 撤销按钮'),
	(11454, 'admin.ai.mcp.token.revoke', 'zh-CN', '撤销', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 撤销按钮'),
	(11455, 'admin.ai.mcp.token.revokeConfirm', 'en-US', 'Revoke this token? It stops working immediately and cannot be restored.', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 撤销二次确认文案'),
	(11456, 'admin.ai.mcp.token.revokeConfirm', 'zh-CN', '确定撤销这把令牌？撤销后立即失效且无法恢复。', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 撤销二次确认文案'),
	(11457, 'admin.ai.mcp.token.revokeDone', 'en-US', 'Token revoked (effective immediately)', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'ai/mcp.html: 撤销成功回执'),
	(11458, 'admin.ai.mcp.token.revokeDone', 'zh-CN', '已撤销该令牌（立即失效）', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'ai/mcp.html: 撤销成功回执'),
	(11459, 'admin.ai.mcp.token.revokedHint', 'en-US', 'Revoked tokens stay in the list (so the audit can answer when they were revoked) but stop working.', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 已撤销说明'),
	(11460, 'admin.ai.mcp.token.revokedHint', 'zh-CN', '已撤销的令牌保留在表里（审计要能回答「什么时候撤的」），但不再可用。', 200, 1, '2026-11-15 20:36:56.050335+08', '2026-11-15 20:36:56.050335+08', 'admin', 'admin/ai/mcp.html: 已撤销说明'),
