INSERT INTO public.sys_i18n VALUES
	(11647, 'admin.customer.rfm.hint.score.lead', 'en-US', 'All three scores are ', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径前段）'),
	(11648, 'admin.customer.rfm.hint.score.lead', 'zh-CN', 'R / F / M 三个分数都是', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径前段）'),
	(11649, 'admin.customer.rfm.hint.score.strong', 'en-US', 'quintiles (relative)', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径加粗词）'),
	(11650, 'admin.customer.rfm.hint.score.strong', 'zh-CN', '五分位（相对分）', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径加粗词）'),
	(11651, 'admin.customer.rfm.hint.score.tail', 'en-US', ': the customers in this range are ranked, the top 20% get 5 and the bottom 20% get 1. The same person gets different scores in a different range — they are not absolute grades, and comparing them across ranges means nothing.', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径后段）'),
	(11652, 'admin.customer.rfm.hint.score.tail', 'zh-CN', '：按这段时间里下单的这批人排队，前 20% 得 5 分、后 20% 得 1 分。同一个人换一个时间段，分数会变 —— 它们不是绝对等级，换个区间比分数没有意义。', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分数口径后段）'),
	(11653, 'admin.customer.rfm.hint.def.strong', 'en-US', 'What the letters mean', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（定义加粗词）'),
	(11654, 'admin.customer.rfm.hint.def.strong', 'zh-CN', '三个字母的意思', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（定义加粗词）'),
	(11655, 'admin.customer.rfm.hint.def.tail', 'en-US', ': R = how long since the last order (more recent scores higher); F = number of orders in this range; M = net spend in this range. The first two count paid-and-later orders only; guest orders (no account) are excluded.', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（定义后段）'),
	(11656, 'admin.customer.rfm.hint.def.tail', 'zh-CN', '：R = 最近一次下单距今多久（越近分越高）；F = 这段时间里下了几单；M = 这段时间的净消费额。前两个都只看计入消费的订单，游客单（没有账号）不计入。', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（定义后段）'),
	(11657, 'admin.customer.rfm.hint.seg.strong', 'en-US', 'Segments', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分段加粗词）'),
	(11658, 'admin.customer.rfm.hint.seg.strong', 'zh-CN', '分段', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分段加粗词）'),
	(11659, 'admin.customer.rfm.hint.seg.tail', 'en-US', ' come from the total score: 12 or more is high value, 8 or more is potential, the rest is general.', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分段后段）'),
	(11660, 'admin.customer.rfm.hint.seg.tail', 'zh-CN', '按三项总分划分：≥12 是高价值，≥8 是潜力，其余是一般。', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 说明（分段后段）'),
	(11661, 'admin.customer.rfm.empty', 'en-US', 'No customers to analyse in this range: either no site project exists yet, or there are no paid orders. Try another range.', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 无数据空态'),
	(11662, 'admin.customer.rfm.empty', 'zh-CN', '这段时间里没有可分析的客户：可能是还没有站点工程，也可能确实没有已付款的订单。换个时间段试试。', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 无数据空态'),
	(11663, 'admin.customer.rfm.scope', 'en-US', 'Range: ', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 区间回显前缀'),
	(11664, 'admin.customer.rfm.scope', 'zh-CN', '范围：', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 区间回显前缀'),
	(11665, 'admin.customer.rfm.col.customer', 'en-US', 'Customer', 200, 1, '2026-11-15 20:36:56.08345+08', '2026-11-15 20:36:56.08345+08', 'admin', 'admin/user/customer_rfm.html: 表头（客户）'),
