INSERT INTO public.sys_i18n VALUES
	(12875, 'admin.inventory.stock_skus.lead', 'zh-CN', '一条货的身份是「仓库 + 仓库 SKU」：', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12876, 'admin.inventory.stock_skus.lead', 'en-US', 'A stock row is identified by warehouse + warehouse SKU: ', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12877, 'admin.inventory.stock_skus.bold', 'zh-CN', '同一条货可以在多个仓各有一行，同一个仓里也可以有多条货', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12878, 'admin.inventory.stock_skus.bold', 'en-US', 'one SKU can exist in several warehouses, and one warehouse can hold several rows for the same product', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12879, 'admin.inventory.stock_skus.tail', 'zh-CN', '（自有码、客户码、不同批次）。编码与所在仓建好之后不可改 —— 改了等于换一条货，历史流水与变体引用都会指空。商品要卖这里的货，挂在商品变体上（引用这一行），不在这里操作。', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12880, 'admin.inventory.stock_skus.tail', 'en-US', ' (own code, customer code, different batches). Code and warehouse are frozen after creation - changing them means a different row, and history plus variant references would dangle. To sell this stock, attach it on the product variant, not here.', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12881, 'admin.inventory.stock_skus.listLead', 'zh-CN', '仓库 SKU（', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12882, 'admin.inventory.stock_skus.listLead', 'en-US', 'Warehouse SKUs (', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
