	(12921, 'admin.inventory.stock_skus.costPh', 'zh-CN', '留空 = 尚未核算（不是 0）', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
	(12922, 'admin.inventory.stock_skus.costPh', 'en-US', 'Leave empty = not costed yet (not 0)', 200, 1, '2026-11-15 20:36:56.237712+08', '2026-11-15 20:36:56.237712+08', 'inventory', 'internal/templates/admin/inventory/inventory_stock_skus.html'),
