INSERT INTO public.sys_i18n VALUES
	(13177, 'admin.inventory_purchases.create.asDraft', 'zh-CN', '存为草稿（先不下单，之后在列表里点「下单」）', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchase_create_form.html'),
	(13178, 'admin.inventory_purchases.create.asDraft', 'en-US', 'Save as draft (not ordered yet; place the order from the list later)', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchase_create_form.html'),
	(13179, 'admin.inventory_purchases.place', 'zh-CN', '下单', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13180, 'admin.inventory_purchases.place', 'en-US', 'Place order', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13181, 'admin.inventory_purchases.placeConfirm', 'zh-CN', '下单？下单后行就锁定，收货按这张单进行。', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13182, 'admin.inventory_purchases.placeConfirm', 'en-US', 'Place this order? Lines are locked afterwards and receipts are posted against it.', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13183, 'admin.inventory_purchases.exception', 'zh-CN', '标记异常', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13184, 'admin.inventory_purchases.exception', 'en-US', 'Mark exception', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13185, 'admin.inventory_purchases.exceptionConfirm', 'zh-CN', '标记异常？标记后暂停收货，直到解除异常。', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13186, 'admin.inventory_purchases.exceptionConfirm', 'en-US', 'Mark this order as an exception? Receiving is paused until the exception is cleared.', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13187, 'admin.inventory_purchases.resume', 'zh-CN', '解除异常', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13188, 'admin.inventory_purchases.resume', 'en-US', 'Clear exception', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13189, 'admin.inventory_purchases.resumeConfirm', 'zh-CN', '解除异常？解除后按已到数量重新判定单据状态，收货入口恢复。', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13190, 'admin.inventory_purchases.resumeConfirm', 'en-US', 'Clear the exception? The status is re-derived from received quantities and receiving opens again.', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13191, 'admin.inventory_purchases.receipt.submitAll', 'zh-CN', '确认收货', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13192, 'admin.inventory_purchases.receipt.submitAll', 'en-US', 'Post receipts', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13193, 'admin.inventory_purchases.receipt.submitHint', 'zh-CN', '本次到货默认填满剩余量；留 0 的行本次不收。', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(13194, 'admin.inventory_purchases.receipt.submitHint', 'en-US', 'Quantity now defaults to the outstanding amount; lines left at 0 are not received this time.', 200, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/templates/admin/purchase/purchases.html'),
	(3958, 'admin.inventory_purchases.intro.tail', 'zh-CN', '由收货原子递增；单据状态里「已下单 / 部分到货 / 已到货」三个由「已入库数量 与 采购数量」推出，草稿 / 异常 / 已完结 / 已取消只由动作推进 —— 表单里没有状态字段。', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:56.286186+08', 'admin', 'internal/templates/admin/purchase/purchases.html'),
	(3959, 'admin.inventory_purchases.intro.tail', 'en-US', ' is increased atomically by each receipt; among the statuses, ordered / partially received / received are derived from the received quantity against the ordered quantity, while draft / exception / finished / cancelled are only advanced by actions — the form has no status field.', 200, 1, '2026-11-15 20:36:55.421206+08', '2026-11-15 20:36:56.286186+08', 'admin', 'internal/templates/admin/purchase/purchases.html'),
	(13197, 'ErrPurchaseStatusInvalid', 'zh-CN', '状态筛选值不在合法状态内（草稿 / 已下单 / 部分到货 / 已到货 / 异常 / 已完结 / 已取消）', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13198, 'ErrPurchaseStatusInvalid', 'en-US', 'The status filter is not one of draft / ordered / partially received / received / exception / finished / cancelled', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(12593, 'ErrPurchaseStatusNotFinishable', 'zh-CN', '只有已到货或部分到货的采购单可以提前关单', 409, 1, '2026-11-15 20:36:56.202259+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(12594, 'ErrPurchaseStatusNotFinishable', 'en-US', 'Only received or partially received purchase orders can be closed early', 409, 1, '2026-11-15 20:36:56.202259+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(12595, 'ErrPurchaseStatusNotCancelable', 'zh-CN', '只有草稿 / 已下单 / 部分到货 / 异常中的采购单可以取消（已到货的货已进仓，要走退货）', 409, 1, '2026-11-15 20:36:56.202259+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(12596, 'ErrPurchaseStatusNotCancelable', 'en-US', 'Only draft / ordered / partially received / exception orders can be cancelled; fully received stock already sits in the warehouse', 409, 1, '2026-11-15 20:36:56.202259+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13203, 'ErrPurchaseStatusNotPlaceable', 'zh-CN', '只有草稿可以下单（已下单的单重复下单不改变任何东西）', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13204, 'ErrPurchaseStatusNotPlaceable', 'en-US', 'Only a draft can be placed; re-placing an ordered purchase order changes nothing', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13205, 'ErrPurchaseStatusNotExceptionable', 'zh-CN', '只有已下单 / 部分到货 / 已到货的采购单可以标记异常（草稿还没下单，已完结 / 已取消的单已经收尾）', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13245, 'pPubHistTAuto', 'zh-CN', '自动重建', 200, 1, '2026-11-15 20:36:56.297126+08', '2026-11-15 20:36:56.297126+08', 'product', 'internal/templates/admin/product/product_publish_records.html'),
	(13206, 'ErrPurchaseStatusNotExceptionable', 'en-US', 'Only ordered / partially received / received purchase orders can be marked as an exception (a draft is not ordered yet; finished and cancelled orders are final)', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13207, 'ErrPurchaseStatusNotResumable', 'zh-CN', '只有异常中的采购单可以解除异常', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13208, 'ErrPurchaseStatusNotResumable', 'en-US', 'Only an order marked as an exception can be resumed', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13209, 'ErrPurchaseStatusNotReceivable', 'zh-CN', '只有已下单 / 部分到货的采购单可以登记收货（草稿还没下单；已到货 / 已完结 / 已取消已收尾；异常要先解除）', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
	(13210, 'ErrPurchaseStatusNotReceivable', 'en-US', 'Only ordered or partially received purchase orders accept receipts (a draft is not ordered; received, finished and cancelled orders are final; clear the exception first)', 409, 1, '2026-11-15 20:36:56.286186+08', '2026-11-15 20:36:56.286186+08', 'inventory', 'internal/module/purchase/enums/purchase_enums.go'),
